	memory->dma[dma].count = memory->io[(GBA_REG_DMA0CNT_LO + dma * (GBA_REG_DMA1CNT_LO - GBA_REG_DMA0CNT_LO)) >> 1];
	if (dma == 3) {
		if (!memory->dma[dma].count) {
			memory->dma[dma].count = 0x10000;
		}
	} else {
		memory->dma[dma].count &= 0x3FFF;
		if (!memory->dma[dma].count) {
			memory->dma[dma].count = 0x4000;
		}
	}
